  options($('backend'),res('backend').map(r=>[r.id,r.id]));
  options($('terrain'),[['','请选择 World 文件或地形'],...(b.worlds||[]).map(p=>[p,p.split('/').at(-1)]),...res('terrain').map(r=>[r.id,({flat:'平地',stairs:'台阶',ramp:'坡道',rough:'随机凸块'}[r.id]||r.id)])]);
  this.resetDraft('');this.events();
