  const task=clone(state.boot.task_template);
  Object.assign(task,{id:(robotId||'robot')+'-task-'+Date.now().toString(36),robot:robotId,policy:'',control:control?.path||'',backend:task.backend||backend?.id||'',world:null,terrain:''});
