  const models=(state.boot.models||[]).filter(m=>m.robots.includes($('robot').value));
  const preferred=modelFile||state.boot.policy_details?.[id]?.model.file||models.find(m=>m.selectable&&m.registered)?.file||models.find(m=>m.selectable)?.file;
  const name=m=>models.filter(other=>other.name===m.name).length>1?m.file.split('/').slice(3).join('/'):m.name;
  options($('policy'),models.map(m=>[m.file,name(m)+(m.selectable?'':' · '+m.reason)]),preferred);
  for(const option of $('policy').options){const m=models.find(m=>m.file===option.value);option.disabled=!m.selectable;option.title=m.file+' · '+m.reason}
  if(!models.some(m=>m.selectable))$('policy').add(new Option($('robot').value?(models.length?'模型存在，暂无可用部署接口':'策略目录中没有模型'):'请先选择机器人',''));
