 fill(e){this.snapshotPolicy=null;$('experiment-id').value=e.id;$('robot').value=e.robot;this.choosePolicies(e.policy,e.model_file);this.resetPolicyPD();$('control').value=e.control;$('backend').value=e.backend;$('terrain').value=e.world||e.terrain;$('seed').value=e.seed??0;$('duration').value=e.runtime.duration_s;setTriple('spawn-position',e.spawn.position);setTriple('spawn-rpy',e.spawn.rpy.map(v=>Number(fmt(W.angle(v),8))));$('spawn-unit-label').textContent='初始姿态 · '+(W.prefs.angle||'rad');$('gui').checked=e.runtime.gui;$('paused').checked=e.runtime.paused;this.control=clone(state.boot.controls.find(c=>c.path===e.control)?.data||null);this.backend=clone(data('backend',e.backend)||null);if(e.overrides?.control)this.control=merge(this.control,e.overrides.control);if(e.overrides?.backend)this.backend=merge(this.backend,e.overrides.backend);this.terrainFields(e.terrain_parameters);this.editors();this.paths();this.joints();this.contract();}
