 editors(){ $('control-json').value=JSON.stringify(this.control,null,2);$('backend-json').value=JSON.stringify(this.backend,null,2);$('control-dt').value=this.control?this.control.timing.control_dt*1000:'';$('decimation').value=this.control?.timing.decimation??'';$('physics-step').value=this.backend?this.backend.physics.step_size*1000:'';this.timing();}
