 payload(validate=true){if(validate&&!$('config-form').reportValidity())throw new Error('请检查资源与参数必填项');if(!this.control||!this.backend)throw new Error('当前机器人尚无已验证的控制配置');const e={schema_version:1,kind:'experiment',id:$('experiment-id').value,robot:$('robot').value,policy:this.selectedModel()?.policy||'',model_file:this.selectedModel()?.file||'',control:$('control').value,backend:$('backend').value,spawn:{position:triple('spawn-position'),rpy:triple('spawn-rpy').map(W.radians)},runtime:{gui:$('gui').checked,paused:$('paused').checked,duration_s:Number($('duration').value)}};if($('terrain').value.endsWith('.world'))e.world=$('terrain').value;else{e.terrain=$('terrain').value;e.seed=Number($('seed').value);e.terrain_parameters={};for(const i of $('terrain-fields').querySelectorAll('input'))e.terrain_parameters[i.dataset.parameter]=Number(i.value)}const out={experiment:e};const pd=this.policyPD,original=this.currentPolicy();if(pd&&original&&(JSON.stringify(pd.kp)!==JSON.stringify(original.actions.kp)||JSON.stringify(pd.kd)!==JSON.stringify(original.actions.kd)||JSON.stringify(pd.reference||original.actions.reference)!==JSON.stringify(original.actions.reference)||(W.finite(pd.vel_scale)&&this.velocityChannels(original).some(c=>c.scale!==pd.vel_scale))))out.policy_pd=clone(pd);const control=JSON.parse($('control-json').value),backend=JSON.parse($('backend-json').value);if(JSON.stringify(control)!==JSON.stringify(state.boot.controls.find(c=>c.path===e.control)?.data))out.control=control;if(!e.world&&JSON.stringify(backend)!==JSON.stringify(data('backend',e.backend)))out.backend=backend;return out;}
 async check(){const rev=this.revision,payload=this.payload();const active=!!state.activeId;if(active&&!W.controller.canEdit())throw new Error('请先停止控制器');const r=await W.api(active?`/api/runs/${encodeURIComponent(state.selected)}/controller`:'/api/check',active?{action:'check',configuration:payload}:payload);if(rev!==this.revision)return W.notice('校验期间参数发生改变，请重新校验。');this.checked=r;if(!active){state.resolved=r.resolved;W.renderer.set(r.terrain,r.resolved);}this.status='已校验，待应用';this.renderEdit();this.showDiagnostics(r.resolved);if(payload.experiment.world){this.backend=clone(r.resolved.backend);this.editors()}W.notice(active?'校验通过，点击应用到控制器。':'模型、关节映射与后端校验通过。参数将在准备新实验后应用。',true)}
