 loaded(s){const r=s.resolved;if(!r)return;if(!res('robot').length){const b=state.boot;b.resources.push({kind:'robot',id:r.selection.robot,manifest:r.experiment.control,data:r.robot},{kind:'policy',id:r.selection.policy,data:{robots:[r.selection.robot]},deployment:{status:'ready',diagnostics:[]},manifest:'运行快照中的策略'},{kind:'backend',id:r.backend.id,data:r.backend});b.controls.push({path:r.experiment.control,data:r.control});b.policy_details={[r.policy.id]:r.policy};if(r.experiment.world)b.worlds=[...(b.worlds||[]),r.experiment.world];options($('robot'),[[r.selection.robot,r.selection.robot]]);options($('control'),[[r.experiment.control,r.control.id]]);options($('backend'),[[r.backend.id,r.backend.id]]);options($('terrain'),[[r.experiment.world||r.experiment.terrain,r.experiment.world?.split('/').at(-1)||r.experiment.terrain]]);}
 this.fill({...r.experiment,model_file:r.policy.model.file});this.snapshotPolicy=clone(r.policy);this.resetPolicyPD(r.policy);this.control=clone(r.control);this.backend=clone(r.backend);this.editors();this.applied=this.captureSafe();this.status='已应用';this.renderEdit();this.contract(r.policy);const unavailable=res('robot').find(x=>x.id===$('robot').value)?.availability?.exists===false;$('resource-availability').textContent=unavailable?'快照模型已校验 · 当前源资产缺失，请检查资源路径':`运行快照已校验 · ${r.policy.joints.length} 关节 / ${r.policy.actions.count} 动作`;this.lock();}
