   const runtimeLocked=active&&!(editable&&this.controllerEditable(i));
   i.disabled=i.dataset.pdReadonly==='true'||i.dataset.referenceReadonly==='true'||((locked||runtimeLocked)&&!['angle-unit','expand-parameters'].includes(i.id));
