 if(owned)state.activeId=s.run_id;if(s&&!owned&&['finished','failed'].includes(s.metadata.state)){const released=!!state.activeId;state.activeId='';state.stopping=false;if(released)W.refreshRuns().catch(()=>{});}W.resources.lock();for(const id of ['velocity-zero','data-velocity-zero'])$(id).disabled=!live||state.mode!=='live';
 W.pill('connection',!state.online?'服务断线':W.signalFresh('controller')?'遥测在线':owned?'遥测等待 / 过期':'服务在线 · ROS 未连接',!state.online?'bad':W.signalFresh('controller')?'good':owned?'warn':'');
 let sim=!s?'仿真未启动':live?(c.simulation_running?'仿真运行中':'仿真已暂停'):runName(s.metadata.state)+(owned?' · 状态未确认':'');if(state.stopping&&s?.metadata.state!=='finished')sim='正在结束实验';W.pill('simulation-state',sim,live?(c.simulation_running?'good':'blue'):s?.metadata.state==='failed'?'bad':'');W.pill('policy-state',live?(W.controller.status().unknown?'控制器状态未知':!W.controller.status().running?'控制器已停止':c.fault?'策略故障':c.fsm_state==='policy'?(c.policy_ready?'策略运行中':'策略等待就绪'):c.fsm_state==='stand'?'站立状态':c.fsm_state==='sit'?'坐下过渡':'被动阻尼'):(owned?'策略状态未知':'策略未启用'),live?(c.fault?'bad':c.fsm_state==='policy'?'blue':''):'');
 $('reconnect').hidden=state.online;$('global-freshness').textContent=live?`控制数据 ${Math.max(0,Date.now()/1000-entry.received_at).toFixed(1)} s 前`:(owned?'遥测过期 / 状态未知':'无实时遥测');
 W.pill('run-state',s?runName(s.metadata.state):'未加载',s?.metadata.state==='failed'?'bad':'');$('start').disabled=state.mode!=='live'||!state.online||!s||s.metadata.state!=='prepared'||!!state.activeId||$('start').classList.contains('loading');$('stop').disabled=state.mode!=='live'||!state.online||!owned||$('stop').classList.contains('loading');for(const b of document.querySelectorAll('[data-command]')){const action=b.dataset.command;b.disabled=!live||!W.controller.status().running||W.controller.status().unknown||W.controller.busy||state.mode!=='live'||b.classList.contains('loading')||(['stand','sit','policy'].includes(action)&&(!c.ready||!c.simulation_running))||(action==='policy'&&c.fsm_state!=='stand')||(action==='sit'&&!['stand','policy'].includes(c.fsm_state));if(action==='toggle')b.textContent=live&&c.simulation_running?'暂停仿真':'继续仿真'}
 const resetAllowed=live&&owned&&state.mode==='live'&&c.reset_robot_mode==='model_pose';
 $('reset-robot').disabled=!resetAllowed||state.robotResetBusy||state.poseResetPending;
 for(const n of $('reset-form').querySelectorAll('input,select'))n.disabled=!!state.robotResetBusy||state.mode!=='live';
